'use strict';

async function lineForms({verify, verifySources}) {
  let lineFormCases = 0;
  for (const version of ['2.3', '2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const segment = 'STRUCTURE S EXTENDS INTERLIS.LineSegment = a: TEXT*10; END S; LINE FORM Curve: S; ';
    const coordinate = 'DOMAIN Coord = COORD 0.000..100.000,0.000..100.000; ';
    for (const [body, expected] of [
      [segment, 'succeeded'],
      [segment + coordinate + 'DOMAIN L = POLYLINE WITH (Curve,STRAIGHTS,ARCS) VERTEX Coord;', 'succeeded'],
      [segment + coordinate + 'STRUCTURE Attrs = END Attrs; DOMAIN L = SURFACE WITH (Curve) VERTEX Coord WITHOUT OVERLAPS > 0.01 LINE ATTRIBUTES Attrs;', version === '2.3' ? 'succeeded' : 'rejected'],
      ['STRUCTURE S = END S; LINE FORM Curve: S;', 'rejected'],
      ['CLASS S = END S; LINE FORM Curve: S;', 'rejected'],
      ['LINE FORM Curve: Missing;', 'rejected'],
      [segment + coordinate + 'DOMAIN L = POLYLINE WITH (Wrong.Curve) VERTEX Coord;', 'rejected'],
      [segment + coordinate + 'DOMAIN L = POLYLINE WITH (Curve,Curve) VERTEX Coord;', 'succeeded'],
      [segment + 'DOMAIN Number = 0..10; L = POLYLINE WITH (Curve) VERTEX Number;', 'rejected'],
      ['STRUCTURE S EXTENDS INTERLIS.StraightSegment = END S; LINE FORM Curve: S;', 'rejected'],
    ]) { await verify(wrap(body), expected); lineFormCases++; }
    await verify(wrap(segment).replace('CONTRACTED ', ''), version === '2.3' ? 'rejected' : 'succeeded'); lineFormCases++;
    const original = wrap(segment + coordinate + 'DOMAIN L = POLYLINE WITH (Curve,STRAIGHTS) VERTEX Coord;').replace('MODEL F', 'MODEL Original').replace('END F.', 'END Original.');
    const translated = wrap(segment.replaceAll('Curve', 'Courbe') + coordinate + 'DOMAIN L = POLYLINE WITH (STRAIGHTS,Courbe) VERTEX Coord;')
      .replace(`INTERLIS ${version}; `, '').replace('VERSION "1" =', 'VERSION "1" TRANSLATION OF Original ["1"] =');
    for (const [text, expected] of [[original + translated, 'succeeded'], [original + translated.replace('STRAIGHTS,Courbe', 'ARCS,Courbe'), 'rejected']]) {
      await verify(text, expected); lineFormCases++;
    }
    for (const reverse of [false, true]) {
      await verifySources([
        {sourceId: reverse ? 'memory:/z-lines.ili' : 'memory:/a-lines.ili', text: wrap(segment).replace('MODEL F', 'MODEL Base').replace('END F.', 'END Base.')},
        {sourceId: reverse ? 'memory:/a-use.ili' : 'memory:/z-use.ili', text: wrap('IMPORTS Base; STRUCTURE Local EXTENDS Base.S = END Local; LINE FORM LocalCurve: Local; ' + coordinate + 'DOMAIN L = POLYLINE WITH (Base.Curve,LocalCurve) VERTEX Coord;')}
      ], 'succeeded'); lineFormCases++;
    }
  }
  return lineFormCases;
}

async function graphicParameters({verify, verifySources}) {
  let graphicCases = 0;
  for (const version of ['2.3','2.4']) {
    const wrap = body => `INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const base = 'DOMAIN Coord = COORD 0.00..100.00,0.00..100.00; TOPIC Signs = CLASS Mark EXTENDS INTERLIS.SIGN = PARAMETER Pos: MANDATORY Coord; Priority: 0..200; END Mark; END Signs; SIGN BASKET Library ~ Signs OBJECTS OF Mark: Dot,Square; TOPIC Data = CLASS Point = pos: Coord; kind: (a,b,c) ORDERED; label: TEXT*20; END Point; END Data; ';
    const graphic = 'TOPIC Maps = DEPENDS ON Data; GRAPHIC Map BASED ON F.Data.Point = WHERE kind != #c; Draw OF F.Signs.Mark: WHERE kind == #a (Sign := {Dot}; Pos := pos; Priority := 10), WHERE kind == #b (Sign := {Square}; Pos := pos; Priority := 20); END Map; END Maps;';
    const body = base + graphic;
    const according = body.replace('Priority := 10','Priority := ACCORDING kind (10 WHEN IN #a..#b, 20 WHEN IN #c)');
    const inherited = body.replace('END Maps;','GRAPHIC Child EXTENDS Map = Draw (EXTENDED): (Priority := 30); END Child; END Maps;');
    for (const [text,expected] of [
      [body,'succeeded'],
      [body.replace('F.Data.Point','Data.Point'),'rejected'],
      [body.replaceAll('F.Signs.Mark','Signs.Mark'),'rejected'],
      [body.replace('WHERE kind != #c','WHERE 10'),'rejected'],
      [body.replace('Priority := 10','Priority := label'),'rejected'],
      [body.replace('Priority := 10','Unknown := 10'),'rejected'],
      [body.replaceAll('Pos := pos; ',''),'rejected'],
      [body.replace('{Dot}','{Missing}'),'rejected'],
      [body.replace('DEPENDS ON Data;',''),'rejected'],
      [body.replaceAll('OF F.Signs.Mark','OF F.Data.Point'),'rejected'],
      [body.replace('END Map;','END Wrong;'),'rejected'],
      [body.replace('WHERE kind == #a','kind == #a'),'rejected'],
      [according,'succeeded'],
      [according.replace(' ORDERED',''),'rejected'],
      [according.replace('#a..#b','#c..#a'),'rejected'],
      [according.replace('ACCORDING kind','ACCORDING label'),'rejected'],
      [according.replace('#a..#b','#a..#missing'),'rejected'],
      [inherited,'succeeded'],
      [inherited.replace('Draw (EXTENDED)','Draw'),'rejected'],
      [inherited.replace('GRAPHIC Map BASED','GRAPHIC Map (FINAL) BASED'),'rejected'],
      [inherited.replace('Draw OF F.Signs.Mark','Draw (FINAL) OF F.Signs.Mark'),'rejected'],
      [body.replace('OBJECTS OF Mark: Dot,Square','OBJECTS OF Mark: Dot,Dot'),'rejected']
    ]) { await verify(wrap(text),expected); graphicCases++; }
    const original=wrap(body).replace('MODEL F','MODEL Original').replace('END F.','END Original.').replaceAll('F.Data.Point','Original.Data.Point').replaceAll('F.Signs.Mark','Original.Signs.Mark');
    const translated=wrap(body.replace('GRAPHIC Map','GRAPHIC Carte').replace('END Map;','END Carte;').replace('Draw OF','Dessiner OF'))
      .replace(`INTERLIS ${version}; `,'').replace('VERSION "1" =','VERSION "1" TRANSLATION OF Original ["1"] =');
    for (const [text,expected] of [[original+translated,'succeeded'],[original+translated.replace('Priority := 10','Priority := 11'),'rejected'],[original+translated.replace('{Dot}','{Square}'),'rejected']]) {
      await verify(text,expected);graphicCases++;
    }
    for(const reverse of [false,true]) {
      await verifySources([
        {sourceId: reverse?'memory:/z-base.ili':'memory:/a-base.ili',text:wrap(base+'TOPIC More EXTENDS Data = END More;').replace('MODEL F','MODEL Base').replace('END F.','END Base.')},
        {sourceId: reverse?'memory:/a-use.ili':'memory:/z-use.ili',text:wrap('IMPORTS Base; SIGN BASKET B ~ Base.Signs OBJECTS OF Mark: Dot; TOPIC Maps = DEPENDS ON Base.Data,Base.More; GRAPHIC G BASED ON Base.More.Point = Draw OF Base.Signs.Mark: (Sign := {Dot}; Pos := pos); END G; END Maps;')}
      ],'succeeded');graphicCases++;
    }
  }
  return graphicCases;
}

async function geometryContracts({verify, verifySources}) {
  let geometryCases = 0;
  for (const version of ['2.3','2.4']) {
    const coord = 'DOMAIN P=COORD 0.000..100.000,0.000..100.000; ';
    const cases = [
      ['DOMAIN L (ABSTRACT)=POLYLINE;', 'succeeded'],
      ['DOMAIN L=POLYLINE;', 'rejected'],
      [coord+'DOMAIN L=POLYLINE VERTEX P;', 'rejected'],
      ['DOMAIN L=POLYLINE WITH (STRAIGHTS);', 'rejected'],
      [coord+'DOMAIN S=SURFACE WITH (STRAIGHTS) VERTEX P;', version==='2.4'?'succeeded':'rejected'],
      [coord+'DOMAIN S=SURFACE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS;', version==='2.4'?'succeeded':'rejected'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS > 0.0001;', version==='2.3'?'succeeded':'rejected'],
      [coord.replaceAll('.000','.000000')+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS > 0.000010;', 'succeeded'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS > 0;', 'rejected'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS > 0.1e-2;', 'succeeded'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P WITHOUT OVERLAPS > 0.010; D EXTENDS L=POLYLINE WITHOUT OVERLAPS > 0.005;', 'rejected'],
      [coord+'DOMAIN L=DIRECTED POLYLINE WITH (STRAIGHTS) VERTEX P; D EXTENDS L=POLYLINE;', 'rejected'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX P; D EXTENDS L=POLYLINE WITH (STRAIGHTS,ARCS);', 'rejected'],
      [coord+'DOMAIN L=POLYLINE WITH (STRAIGHTS,ARCS) VERTEX P; D EXTENDS L=DIRECTED POLYLINE WITH (STRAIGHTS); TOPIC T=CLASS C=l:D; END C; VIEW V INSPECTION OF c~C->l; = p:=c->Segments[FIRST]->SegmentEndPoint; END V; END T;', 'succeeded'],
      ['DOMAIN P=COORD 0.00..100.00,0.000..100.000; L=POLYLINE WITH (STRAIGHTS) VERTEX P;', version==='2.3'?'succeeded':'rejected'],
      [coord+'STRUCTURE S(ABSTRACT) EXTENDS INTERLIS.LineSegment = middle(ABSTRACT):INTERLIS.LineCoord; MANDATORY CONSTRAINT DEFINED(middle); END S; LINE FORM Curve:S; TOPIC T=CLASS C=l:POLYLINE WITH (Curve) VERTEX P; END C; VIEW V INSPECTION OF c~C->l; = p:=c->Segments[FIRST]->SegmentEndPoint; END V; END T;', 'succeeded']
    ];
    for (const [body, expected] of cases) {
      await verify(`INTERLIS ${version}; CONTRACTED MODEL F AT "x" VERSION "1" = ${body} END F.`,expected); geometryCases++;
    }
    for (const reversed of [false,true]) {
      const sources = [
        {sourceId:'memory:/g2-segments/base.ili',text:`INTERLIS ${version}; CONTRACTED MODEL Base AT "x" VERSION "1" = STRUCTURE Foreign=label:TEXT; END Foreign; STRUCTURE Data(ABSTRACT)=p(ABSTRACT):INTERLIS.LineCoord; END Data; STRUCTURE S(ABSTRACT) EXTENDS INTERLIS.LineSegment = SegmentEndPoint(EXTENDED,ABSTRACT):MANDATORY; data:BAG OF Data; other:Foreign; copy(ABSTRACT):INTERLIS.LineCoord:=SegmentEndPoint; MANDATORY CONSTRAINT DEFINED(SegmentEndPoint); MANDATORY CONSTRAINT DEFINED(other); END S; LINE FORM Curve:S; END Base.`},
        {sourceId:'memory:/g2-segments/use.ili',text:`INTERLIS ${version}; MODEL F AT "x" VERSION "1" = IMPORTS Base; DOMAIN P2=COORD 0.00..100.00,0.00..100.00; P3=COORD 0.000..100.000,0.000..100.000,0.000..100.000; TOPIC T=CLASS C=line2:POLYLINE WITH (Base.Curve) VERTEX P2; line3:POLYLINE WITH (Base.Curve) VERTEX P3; END C; VIEW V2 INSPECTION OF l~C->line2; = p:=l->Segments[FIRST]->SegmentEndPoint; END V2; VIEW V3 INSPECTION OF l~C->line3; = p:=l->Segments[FIRST]->SegmentEndPoint; END V3; END T; END F.`}
      ];
      if(reversed)sources.reverse(); await verifySources(sources,'succeeded'); geometryCases++;
    }
  }
  for (const version of ['2.3','2.4']) for (const reverse of [false,true]) {
    const sources=[
      {sourceId:reverse?'memory:/a-base.ili':'memory:/z-base.ili',text:`INTERLIS ${version}; MODEL Base AT "https://example.org" VERSION "1" = UNIT Kilometre[km]=1000 [INTERLIS.m]; Short[short]=0.001 [km]; DOMAIN P=COORD 0.000..100.000 [short],0.000..100.000 [short]; END Base.`},
      {sourceId:reverse?'memory:/z-use.ili':'memory:/a-use.ili',text:`INTERLIS ${version}; MODEL F AT "https://example.org" VERSION "1" = IMPORTS Base; DOMAIN L=POLYLINE WITH (STRAIGHTS) VERTEX Base.P; END F.`}
    ];
    await verifySources(sources,'succeeded'); geometryCases++;
  }
  const originalGeometryCases = [{"text": "INTERLIS 2.3; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; STRUCTURE S EXTENDS INTERLIS.LineSegment = x: TEXT; END S; LINE FORM Curve: S; TOPIC T = CLASS A = line: POLYLINE WITH (Curve) VERTEX Coord; END A; VIEW V INSPECTION OF line~A->line; = END V; END T; END F.", "roots": ["F"], "expected": "succeeded"}, {"text": "INTERLIS 2.4; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; STRUCTURE S EXTENDS INTERLIS.LineSegment = x: TEXT; END S; LINE FORM Curve: S; TOPIC T = CLASS A = line: POLYLINE WITH (Curve) VERTEX Coord; END A; VIEW V INSPECTION OF line~A->line; = END V; END T; END F.", "roots": ["F"], "expected": "succeeded"}, {"text": "INTERLIS 2.3; MODEL M AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.000000..100.000000,0.000000..100.000000; L = SURFACE WITH (STRAIGHTS) VERTEX Coord WITHOUT OVERLAPS > 0.00001; END M.\n", "roots": ["M"], "expected": "succeeded"}, {"text": "INTERLIS 2.4; MODEL M AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.000000..100.000000,0.000000..100.000000; L = SURFACE WITH (STRAIGHTS) VERTEX Coord WITHOUT OVERLAPS > 0.00001; END M.\n", "roots": ["M"], "expected": "rejected"}, {"text": "INTERLIS 2.3; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; TOPIC T = CLASS A = kind: TEXT*10; area: AREA WITH (STRAIGHTS) VERTEX Coord; END A; VIEW V AREA INSPECTION OF edge~A->area; = left := THISAREA->kind; right := THATAREA->kind; END V; END T; END F.", "roots": ["F"], "expected": "rejected"}, {"text": "INTERLIS 2.3; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; STRUCTURE Attrs = label: TEXT; END Attrs; TOPIC T = CLASS A = area: SURFACE WITH (STRAIGHTS) VERTEX Coord; END A; VIEW V INSPECTION OF edge~A->area; = ALL OF edge; END V; END T; END F.", "roots": ["F"], "expected": "rejected"}, {"text": "INTERLIS 2.4; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; TOPIC T = CLASS A = kind: TEXT*10; area: AREA WITH (STRAIGHTS) VERTEX Coord; END A; VIEW V AREA INSPECTION OF edge~A->area; = left := THISAREA->kind; right := THATAREA->kind; END V; END T; END F.", "roots": ["F"], "expected": "succeeded"}, {"text": "INTERLIS 2.4; CONTRACTED MODEL F AT \"https://example.org\" VERSION \"1\" = DOMAIN Coord = COORD 0.00..100.00,0.00..100.00,0.00..100.00; STRUCTURE Attrs = label: TEXT; END Attrs; TOPIC T = CLASS A = area: SURFACE WITH (STRAIGHTS) VERTEX Coord; END A; VIEW V INSPECTION OF edge~A->area; = ALL OF edge; END V; END T; END F.", "roots": ["F"], "expected": "succeeded"}];
  for (const c of originalGeometryCases) { await verifySources([{sourceId:"memory:/g2-geometry/original.ili",text:c.text}],c.expected,c.roots); geometryCases++; }
  return geometryCases;
}

async function signatures({verify, verifySources}) {
  let signatureCases = 0;
  for (const version of ['2.3','2.4']) {
    const types='TOPIC Signs = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Most EXTENDS Derived = PARAMETER C: MANDATORY 0..10; END Most; CLASS Other EXTENDS INTERLIS.SIGN = END Other; CLASS Colour EXTENDS INTERLIS.SIGN = END Colour; END Signs; ';
    const body=(actual,signature,assignments)=>types+`SIGN BASKET Library ~ Signs OBJECTS OF ${actual}: Dot; TOPIC Data = CLASS Feature = kind:(a,b) ORDERED; visible:BOOLEAN; END Feature; GRAPHIC G BASED ON Feature = Draw OF F.Signs.${signature}: (Sign := {Dot}; ${assignments}); END G; END Data;`;
    const wrap=body=>`INTERLIS ${version}; CONTRACTED MODEL F AT "https://example.org" VERSION "1" = ${body} END F.`;
    const cases=[
      [body('S','Most','A := 1'),'succeeded'],
      [body('S','Derived','A := 1; B := 2'),'succeeded'],
      [body('S','Most','A := 1; B := 2'),'succeeded'],
      [body('S','Most','A := 1; B := 2; C := 3'),'succeeded'],
      [body('S','Most','A := 1; C := 3'),'rejected'],
      [body('S','Derived','B := 2'),'rejected'],
      [body('Derived','S','A := 1'),'rejected'],
      [body('Most','Most','A := 1; B := 2'),'rejected'],
      [body('Other','Derived','A := 1; B := 2'),'rejected']
    ];
    const restricted=body('S','Derived','A := 1; B := 2').replace('PARAMETER B:','PARAMETER Sign(EXTENDED):METAOBJECT OF Derived; B:');
    cases.push([restricted,'rejected'],[restricted.replace('OBJECTS OF S:','OBJECTS OF Derived:'),'succeeded']);
    const colour=body('S','S','A := 1; Colour := {Paint}').replace('A: MANDATORY','Colour:METAOBJECT OF F.Signs.Colour; A: MANDATORY').replace('OBJECTS OF S: Dot;','OBJECTS OF S: Dot OBJECTS OF Colour: Paint;');
    cases.push([colour,'succeeded'],[colour.replace('Colour := {Paint}','Colour := {Dot}'),'rejected'],[colour.replace('Colour:METAOBJECT OF F.Signs.Colour','Colour:METAOBJECT'),'rejected'],[colour.replace('Colour:METAOBJECT OF F.Signs.Colour','Colour:METAOBJECT').replace('Colour := {Paint}','Colour := {Dot}'),'succeeded']);
    const inheritedRestriction=body('S','S','A := 1').replace('PARAMETER B:','PARAMETER Sign(EXTENDED):METAOBJECT OF Derived; B:').replace('END Data;','GRAPHIC H EXTENDS G = Draw(EXTENDED) OF F.Signs.Derived:(A := 1); END H; END Data;');
    cases.push([inheritedRestriction,'rejected'],[inheritedRestriction.replace('OBJECTS OF S: Dot;','OBJECTS OF S: Dot OBJECTS OF Derived: Special;').replace('Derived:(A := 1)','Derived:(Sign := {Special}; A := 1; B := 2)'),'succeeded']);

    const inherited=body('S','S','A := 1').replace('END Data;','GRAPHIC H EXTENDS G = Draw(EXTENDED) OF F.Signs.Most:(B := 2); END H; END Data;');
    cases.push([inherited,'succeeded'],[inherited.replace('(B := 2)','(C := 3)'),'rejected']);
    const narrowed=body('S','S','A := 9').replace('PARAMETER B:','PARAMETER A(EXTENDED):MANDATORY 0..5; B:').replace('END Data;','GRAPHIC H EXTENDS G = Draw(EXTENDED) OF F.Signs.Derived:(B := 2); END H; END Data;');
    cases.push([narrowed,'rejected'],[narrowed.replace('A := 9','A := 4'),'succeeded'],[narrowed.replace('(B := 2)','(A := 4; B := 2)'),'succeeded']);
    const conditional=narrowed.replace('(B := 2)','WHERE visible == #true (A := 4; B := 2)');
    cases.push([conditional,'succeeded'],[conditional.replace('Draw OF F.Signs.S: (','Draw OF F.Signs.S: WHERE visible == #true ('),'succeeded']);
    const according=body('S','Derived','A := 1; B := 2').replace('OBJECTS OF S: Dot;','OBJECTS OF S: Dot OBJECTS OF Derived: Special;').replace('(Sign := {Dot}; A := 1; B := 2)','WHERE visible == #true (Sign := ACCORDING kind ({Dot} WHEN IN #a,{Special} WHEN IN #b); A := 1; B := 2)');
    cases.push([according,'succeeded'],[according.replace('; B := 2',''),'rejected']);
    const translationBody=body('S','Derived','A := 1; B := 2').replace('OBJECTS OF S: Dot;','OBJECTS OF S: Dot,Square;');
    const original=wrap(translationBody).replace('MODEL F','MODEL Original').replace('END F.','END Original.').replaceAll('F.Signs.','Original.Signs.');
    const translated=wrap(translationBody).replace(`INTERLIS ${version}; `,'').replace('VERSION "1" =','VERSION "1" TRANSLATION OF Original ["1"] =');
    for(const [b,expected] of cases){await verify(wrap(b),expected);signatureCases++;}
    await verify(original+translated,'succeeded');signatureCases++;
    await verify(original+translated.replace('Sign := {Dot}','Sign := {Square}'),'rejected');signatureCases++;
    for(const reverse of [false,true]) {
      const base=wrap(types).replace('MODEL F','MODEL Base').replace('END F.','END Base.');
      const use=wrap(body('S','Derived','A := 1; B := 2').replace(types,'IMPORTS Base; ').replace('~ Signs','~ Base.Signs').replaceAll('F.Signs.','Base.Signs.'));
      await verifySources([{sourceId:reverse?'memory:/z-base.ili':'memory:/a-base.ili',text:base},{sourceId:reverse?'memory:/a-use.ili':'memory:/z-use.ili',text:use}],'succeeded');signatureCases++;
    }
  }
  const originalSignatureCases = [{"name": "2.3-Derived.ili", "text": "INTERLIS 2.3; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF Derived: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "succeeded"}, {"name": "2.3-Other.ili", "text": "INTERLIS 2.3; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF Other: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "rejected"}, {"name": "2.3-S.ili", "text": "INTERLIS 2.3; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF S: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "succeeded"}, {"name": "2.4-Derived.ili", "text": "INTERLIS 2.4; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF Derived: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "succeeded"}, {"name": "2.4-Other.ili", "text": "INTERLIS 2.4; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF Other: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "rejected"}, {"name": "2.4-S.ili", "text": "INTERLIS 2.4; CONTRACTED MODEL M AT \"https://example.org\" VERSION \"1\" = TOPIC T = CLASS S EXTENDS INTERLIS.SIGN = PARAMETER A: MANDATORY 0..10; END S; CLASS Derived EXTENDS S = PARAMETER B: MANDATORY 0..10; END Derived; CLASS Other EXTENDS INTERLIS.SIGN = END Other; END T; SIGN BASKET Library ~ T OBJECTS OF S: Dot; TOPIC Data = CLASS C = x: TEXT; END C; GRAPHIC G BASED ON C = Draw OF M.T.Derived: (Sign := {Dot}; A := 1; B := 2); END G; END Data; END M.", "expected": "succeeded"}];
  for(const c of originalSignatureCases){await verifySources([{sourceId:"memory:/g2-signatures/"+c.name,text:c.text}],c.expected,["M"]);signatureCases++;}
  return signatureCases;
}

